package com.smartinternship.controller; import com.smartinternship.model.Application; import com.smartinternship.repository.ApplicationRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/applications") public class ApplicationController { private final ApplicationRepository r; public ApplicationController(ApplicationRepository r){this.r=r;} @GetMapping public List<Application> all(){return r.findAll();} @GetMapping("/student/{id}") public List<Application> byStudent(@PathVariable Long id){return r.findByStudentId(id);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Application apply(@RequestBody Application a){return r.save(new Application(a.getStudentId(),a.getOfferId()));} }